function patternHollowDiamond(n) {
  let rows = [];
  // Top half
  for (let i = 0; i < n; i++) {
    let row = '';
    for (let j = 0; j < n - 1 - i; j++) row += ' ';
    if (i === 0) {
      row += '*';
    } else {
      row += '*';
      for (let k = 0; k < 2 * i - 1; k++) row += ' ';
      row += '*';
    }
    rows.push(row);
  }
  // Bottom half
  for (let i = 0; i < n; i++) {
    let row = '';
    for (let j = 0; j < i; j++) row += ' ';
    if (i === n - 1) {
      row += '*';
    } else {
      row += '*';
      for (let k = 0; k < 2 * (n - 1 - i) - 1; k++) row += ' ';
      row += '*';
    }
    rows.push(row);
  }
  return rows.join('\n');
}

