function patternHollowDiamond(n) {
  let rows = [];
  for (let i = 0; i < n; i++) {
    if (i === 0) {
      rows.push(' '.repeat(n - 1) + '*');
    } else {
      rows.push(' '.repeat(n - 1 - i) + '*' + ' '.repeat(2 * i - 1) + '*');
    }
  }
  for (let i = 0; i < n; i++) {
    if (i === n - 1) {
      rows.push(' '.repeat(n - 1) + '*');
    } else {
      rows.push(' '.repeat(i) + '*' + ' '.repeat(2 * (n - 1 - i) - 1) + '*');
    }
  }
  return rows.join('\n');
}
